  Ng: vec3<f32>, rayLength: f32,
  wi: vec3<f32>, tu: f32,
  E: vec3<f32>, tv: f32,
  Tr: vec3<f32>, pad0: f32,
  prim: u32, shader: u32, triFlags: u32, runtimeFlag: u32,
